ROOT=Path('/opt/onixbit-site');BACKUP=ROOT/'cleanup-backups'/'20261006-retired-previews';PROXY='onixbit-site-caddy-1'
REPORT={'status':'RUNNING','mode':sys.argv[1] if len(sys.argv)==2 else None,'removedContainers':[],'removedPaths':[]}
def need(v,c):
 if not v:raise RuntimeError(c)
def run(*args):
 p=subprocess.run(args,capture_output=True,text=True,timeout=90);need(p.returncode==0,'COMMAND_FAILED_'+args[0].upper());return p.stdout.strip()
def field(n,f):return json.loads(run('docker','inspect','--format','{{json '+f+'}}',n))
def identity(n):return {'name':n,'id':field(n,'.Id'),'image':field(n,'.Image'),'running':field(n,'.State.Running'),'startedAt':field(n,'.State.StartedAt'),'mounts':[{k:m.get(k) for k in ['Type','Source','Destination','RW']} for m in field(n,'.Mounts')]}
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def http(url):
 with urllib.request.urlopen(urllib.request.Request(url,headers={'Accept-Encoding':'identity'}),timeout=25) as r:
  b=r.read(8*1024**2+1);need(len(b)<=8*1024**2,'HTTP_BOUND');return {'status':r.status,'sha256':hashlib.sha256(b).hexdigest(),'robots':r.headers.get('X-Robots-Tag','')}
def protected():
 p=Path(PLAN['configPath']);need(p.resolve()==p and not p.is_symlink(),'CONFIG_PATH');s=p.stat();need(digest(p)==PLAN['configSHA256'] and f'{s.st_dev}:{s.st_ino}'==PLAN['configInode'],'CONFIG_DRIFT');need(run('docker','exec',PROXY,'sha256sum','/etc/caddy/Caddyfile').split()[0]==PLAN['configSHA256'],'BOUND_CONFIG_DRIFT');need(str((ROOT/'current').resolve())==PLAN['current'],'CURRENT_DRIFT')
 for c in PLAN['keepContainers']:need(identity(c['name'])==c,'PROTECTED_CONTAINER_DRIFT')
 result={u:http(u) for u in PLAN['http']};need(result==PLAN['http'],'PROTECTED_HTTP_DRIFT');return result

def target(e):
 rel=Path(e['path']);need(len(rel.parts)==2 and rel.parts[0]=='previews' and re.fullmatch(r'2026[0-9a-z-]+',rel.parts[1]),'TARGET_PATH_SCOPE');p=ROOT/rel;need(p.is_dir() and not p.is_symlink() and p.resolve()==p,'TARGET_NOT_REAL_DIRECTORY');need(p.stat().st_dev==ROOT.stat().st_dev and abs(p.stat().st_mtime-e['mtime'])<.000001,'TARGET_IDENTITY_DRIFT')
 need(not Path(PLAN['configPath']).is_relative_to(p) and not Path(PLAN['current']).is_relative_to(p),'PROTECTED_PATH_IN_TARGET')
 ids=[q.read_text().strip() for q in [p/'.next/BUILD_ID',p/'runtime/.next/BUILD_ID'] if q.is_file() and not q.is_symlink() and q.stat().st_size<100];need(ids==e['buildIds'],'TARGET_BUILD_DRIFT')
 for c in PLAN['keepContainers']:
  for m in c['mounts']:
   source=m.get('Source');need(not source or not Path(source).is_relative_to(p),'PRESERVED_MOUNT_IN_TARGET')
 allowed={'node_modules','.next','public','package.json','package-lock.json','server.js','Caddyfile','index.html','assets','company.html','favicon.ico','release.json','.release.json'}
 names={x.name for x in p.iterdir()};need(names<=allowed,'UNREVIEWED_TOP_LEVEL_FILES')
 return p,sorted(names)

def journal():
 q=BACKUP/'result.next';q.write_text(json.dumps(REPORT,indent=2)+'\n');os.replace(q,BACKUP/'result.json')

def main():
 need(REPORT['mode'] in ('--plan','--apply'),'EXACT_MODE');need(len(PLAN['http'])==7,'PROTECTED_HTTP_CONTRACT');need(BACKUP.resolve()==BACKUP and not BACKUP.parent.is_symlink(),'BACKUP_PATH');need(ROOT.is_dir() and ROOT.resolve()==ROOT,'ROOT_SCOPE');need(shutil.rmtree.avoids_symlink_attacks,'FD_SAFE_RMTREE_REQUIRED')
 locks=[]
 for n in ('.full-site-publish.lock','.demo-publish.lock'):
  fd=os.open(ROOT/n,os.O_RDONLY|os.O_NOFOLLOW);need(stat.S_ISREG(os.fstat(fd).st_mode),'LOCK_NOT_REGULAR');fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB);locks.append(fd)
 try:
  REPORT['beforeHttp']=protected();REPORT['diskFreeBefore']=shutil.disk_usage(ROOT).free
  names=set(run('docker','ps','-a','--format','{{.Names}}').splitlines());expected={c['name'] for c in PLAN['keepContainers']+PLAN['targetContainers']};need({n for n in names if re.fullmatch('onixbit-[a-z0-9-]+',n)}==expected,'CONTAINER_SET_DRIFT')
  config=Path(PLAN['configPath']).read_text()
  for c in PLAN['targetContainers']:
   need(identity(c['name'])==c and c['name'] not in config,'TARGET_CONTAINER_DRIFT_OR_REFERENCED')
   if c['running']:need(c['name'].startswith('onixbit-demo-') and field(c['name'],'.HostConfig.PortBindings') in (None,{}),'UNREVIEWED_RUNNING_TARGET')
  REPORT['validatedTargets']=[{'path':e['path'],'topLevel':target(e)[1],'expectedBytesOnDisk':e['bytesOnDisk']} for e in PLAN['directories']]
  if REPORT['mode']=='--plan':REPORT['status']='TARGETS_VALIDATED';return
  need(not BACKUP.exists() and not BACKUP.is_symlink(),'CLEANUP_ALREADY_STARTED');BACKUP.mkdir(parents=True,mode=0o700);(BACKUP/'plan.json').write_text(json.dumps(PLAN,indent=2)+'\n');(BACKUP/'Caddyfile.before').write_bytes(Path(PLAN['configPath']).read_bytes());journal()
  for c in PLAN['targetContainers']:
   need(identity(c['name'])==c,'TARGET_CHANGED_BEFORE_REMOVE')
   if c['running']:run('docker','stop','--time','30',c['id'])
   need(field(c['name'],'.State.Running') is False and field(c['name'],'.Id')==c['id'],'TARGET_STOP_FAILED');run('docker','rm',c['id']);REPORT['removedContainers'].append({'name':c['name'],'id':c['id']});journal()
  REPORT['afterContainerHttp']=protected()
  for e in PLAN['directories']:
   p,_=target(e);shutil.rmtree(p);REPORT['removedPaths'].append(e['path']);journal()
  REPORT['afterHttp']=protected();REPORT['diskFreeAfter']=shutil.disk_usage(ROOT).free;REPORT['freedBytes']=REPORT['diskFreeAfter']-REPORT['diskFreeBefore'];REPORT['status']='CLEANUP_PASS';journal()
 finally:
  for fd in locks:os.close(fd)
try:main()
except Exception as e:
 REPORT['status']='STOP';REPORT['failure']=str(e) if type(e) is RuntimeError else type(e).__name__
 if BACKUP.is_dir():journal()
raw=json.dumps(REPORT).encode();encoded=raw.hex().translate(str.maketrans('0123456789abcdef','abcdefghijklmnop'))
for i,start in enumerate(range(0,len(encoded),8192)):print('ONIXBIT_CLEANUP_CHUNK_'+format(i,'08x').translate(str.maketrans('0123456789abcdef','abcdefghijklmnop'))+'='+encoded[start:start+8192])
print('ONIXBIT_CLEANUP_END_AP='+json.dumps({'chunks':(len(encoded)+8191)//8192,'sha256':hashlib.sha256(raw).hexdigest()}).encode().hex().translate(str.maketrans('0123456789abcdef','abcdefghijklmnop')))
sys.exit(0 if REPORT['status'] in ('TARGETS_VALIDATED','CLEANUP_PASS') else 1)
